import React, { useState, useRef, useEffect, useCallback } from "react";
import { attendanceAPI } from "./api_service";

// ================= CONFIG =================
const CAPTURE_INTERVAL_DEFAULT = 1500;
const CAPTURE_INTERVAL_FAST = 600;
const CONFIDENCE_THRESHOLD = 0.5;

// ================= COMPONENT =================
const CameraRecognition = ({ addNotification }) => {
  // ===== REFS =====
  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const streamRef = useRef(null);
  const timeoutRef = useRef(null);

  // ===== STATE =====
  const [cameraActive, setCameraActive] = useState(false);
  const [autoMode, setAutoMode] = useState(false);
  const [loading, setLoading] = useState(false);

  const [capturedImage, setCapturedImage] = useState(null);
  const [registeredPhotoUrl, setRegisteredPhotoUrl] = useState(null);
  const [faceBox, setFaceBox] = useState(null);

  const [status, setStatus] = useState("idle");
  const [lastResult, setLastResult] = useState(null);
  const [lastDetectionTime, setLastDetectionTime] = useState(null);

  const [successCount, setSuccessCount] = useState(0);
  const [errorCount, setErrorCount] = useState(0);
  const [frameCount, setFrameCount] = useState(0);

  const [errorDetails, setErrorDetails] = useState(null);

  // ================= CAMERA =================
  const startCamera = async () => {
    try {
      setLoading(true);
      setErrorDetails(null);

      const stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: "user" },
        audio: false,
      });

      streamRef.current = stream;

      if (videoRef.current) {
        videoRef.current.srcObject = stream;

        videoRef.current.onloadedmetadata = async () => {
          try {
            await videoRef.current.play();
          } catch (e) {
            console.warn("Lecture forcée requise");
          }

          setCameraActive(true);
          setAutoMode(true);
          setLoading(false);

          addNotification?.("Caméra démarrée", "success");
        };
      }
    } catch (err) {
      handleError(err);
      setLoading(false);
    }
  };

  const stopAll = () => {
    if (timeoutRef.current) clearTimeout(timeoutRef.current);

    if (streamRef.current) {
      streamRef.current.getTracks().forEach((t) => t.stop());
      streamRef.current = null;
    }

    if (videoRef.current) videoRef.current.srcObject = null;

    setCameraActive(false);
    setAutoMode(false);
    setFaceBox(null);
    setStatus("idle");
  };

  // ================= ERROR HANDLER =================
  const handleError = (err) => {
    console.error("[ERROR]", err.response || err);

    const isNetworkError = !err.response;

    const errorObj = {
      code: err.response?.status,
      statusText: err.response?.statusText,
      message:
        err.response?.data?.error ||
        err.response?.data?.message ||
        err.message,
      raw: err.message,
      network: isNetworkError,
    };

    setErrorDetails(errorObj);
    setStatus("error");
    setErrorCount((p) => p + 1);
  };

  // ================= DRAW FACE BOX =================
  const drawFaceBox = useCallback(() => {
    const canvas = canvasRef.current;
    const video = videoRef.current;

    if (!canvas || !video || !faceBox) return;

    const ctx = canvas.getContext("2d");
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const [x, y, w, h] = faceBox;

    ctx.strokeStyle = "lime";
    ctx.lineWidth = 3;
    ctx.strokeRect(x, y, w, h);
  }, [faceBox]);

  useEffect(() => {
    drawFaceBox();
  }, [faceBox, drawFaceBox]);

  // ================= CAPTURE =================
  const captureFrame = useCallback(async () => {
    if (!videoRef.current) return;

    try {
      const canvas = document.createElement("canvas");
      canvas.width = videoRef.current.videoWidth;
      canvas.height = videoRef.current.videoHeight;

      const ctx = canvas.getContext("2d");
      ctx.drawImage(videoRef.current, 0, 0);

      const base64 = canvas.toDataURL("image/jpeg", 0.85);
      const rawBase64 = base64.split(",")[1]; // IMPORTANT

      setCapturedImage(base64);
      setFrameCount((p) => p + 1);

      const res = await attendanceAPI.recognize(rawBase64);
      const data = res?.data || res;

      const confidence = data.confidence || 0;

      if (data.face_box) setFaceBox(data.face_box);

      if (data.success && data.student) {
        setStatus("success");
        setLastResult(data);
        setRegisteredPhotoUrl(data.registered_photo_url);
        setLastDetectionTime(new Date().toLocaleTimeString());
        setSuccessCount((p) => p + 1);

        addNotification?.(`${data.student} reconnu`, "success");

        setAutoMode(false);
        setTimeout(() => setAutoMode(true), 4000);
      } else if (confidence >= CONFIDENCE_THRESHOLD) {
        setStatus("warning");
        setErrorDetails({
          message: `Confiance faible (${(confidence * 100).toFixed(1)}%)`,
        });
      } else {
        setStatus("error");
        setErrorDetails({
          message: "Visage non reconnu",
        });
      }
    } catch (err) {
      handleError(err);
    }

    if (autoMode) {
      timeoutRef.current = setTimeout(
        captureFrame,
        faceBox ? CAPTURE_INTERVAL_FAST : CAPTURE_INTERVAL_DEFAULT
      );
    }
  }, [autoMode, faceBox]);

  // ================= LOOP =================
  useEffect(() => {
    if (autoMode && cameraActive) {
      timeoutRef.current = setTimeout(captureFrame, 500);
    }
    return () => clearTimeout(timeoutRef.current);
  }, [autoMode, cameraActive, captureFrame]);

  // ================= MANUAL =================
  const manualCapture = async () => {
    setLoading(true);
    await captureFrame();
    setLoading(false);
  };

  // ================= UI =================
  return (
    <div className="container">
      <h1>Reconnaissance Faciale</h1>

      {/* VIDEO */}
      <div className="video-box">
        <video
          ref={videoRef}
          autoPlay
          playsInline
          muted={true}
          aria-label="Flux caméra"
        />
        <canvas ref={canvasRef} className="overlay" />

        <div className={`badge ${status}`} aria-label="Statut">
          {status}
        </div>
      </div>

      {/* CONTROLS */}
      <div className="controls">
        {!cameraActive ? (
          <button onClick={startCamera} aria-label="Démarrer caméra">
            ▶️ Démarrer Auto
          </button>
        ) : (
          <>
            <button onClick={manualCapture} aria-label="Capture">
              📸 Capturer maintenant
            </button>

            <button
              onClick={() => setAutoMode((p) => !p)}
              aria-label="Toggle auto"
            >
              {autoMode ? "⏹ Arrêter Auto" : "▶️ Démarrer Auto"}
            </button>

            <button onClick={stopAll} aria-label="Stop caméra">
              🛑 Fermer Caméra
            </button>
          </>
        )}
      </div>

      {/* IMAGES */}
      <div className="grid">
        <div>
          <h3>Capture</h3>
          {capturedImage ? (
            <img src={capturedImage} alt="capture" />
          ) : (
            <p>Aucune capture disponible</p>
          )}
        </div>

        <div>
          <h3>Référence</h3>
          {registeredPhotoUrl ? (
            <img src={registeredPhotoUrl} alt="ref" />
          ) : (
            <div className="placeholder">👤</div>
          )}
        </div>
      </div>

      {/* SUCCESS */}
      {status === "success" && lastResult && (
        <div className="success">
          <p>Nom: {lastResult.student}</p>
          <p>Email: {lastResult.email}</p>
          <p>Confiance: {(lastResult.confidence * 100).toFixed(1)}%</p>
          <p>ID: {lastResult.attendance_id}</p>
          <p>Heure: {lastDetectionTime}</p>
        </div>
      )}

      {/* ERROR */}
      {errorDetails && (
        <div className="error">
          <p>❌ Erreur API</p>
          {errorDetails.code && <p>Code: {errorDetails.code}</p>}
          {errorDetails.statusText && (
            <p>Status: {errorDetails.statusText}</p>
          )}
          <p>Message: {errorDetails.message}</p>
          {errorDetails.network && (
            <p>❌ Erreur réseau ou CORS</p>
          )}
        </div>
      )}

      {/* STATS */}
      <div className="stats">
        <p>Succès: {successCount}</p>
        <p>Échecs: {errorCount}</p>
        <p>Frames: {frameCount}</p>
        <p>Dernière: {lastDetectionTime || "-"}</p>
      </div>

      <style>{`
        .video-box { position:relative; }
        video { width:100%; border-radius:12px; }
        .overlay { position:absolute; top:0; left:0; width:100%; height:100%; }
        .badge { position:absolute; top:10px; right:10px; padding:8px; color:white; }
        .success { background:#d1fae5; padding:10px; }
        .error { background:#fee2e2; padding:10px; }
        .placeholder { height:200px; display:flex; align-items:center; justify-content:center; font-size:40px; }
      `}</style>
    </div>
  );
};

export default CameraRecognition;
